-- PostgreSQL version of h2/V1__create_orders_tables.sql (same version, same description, same tables and columns).
-- Only the id columns differ: BIGINT AUTO_INCREMENT becomes BIGINT GENERATED BY DEFAULT AS IDENTITY.
-- The schema (order_svc) is created by Flyway itself, see spring.flyway.schemas in application-postgres.yml.

-- Orders and their lines.
-- An order is saved as PENDING first, then becomes CONFIRMED (all stock reserved) or REJECTED (stock short or a service failed).
CREATE TABLE IF NOT EXISTS orders (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- The "sub" claim of the token of the person who ordered
    user_id BIGINT NOT NULL,
    -- The "email" claim of that token (for reading only, never used to find a person)
    user_email VARCHAR(255),
    status VARCHAR(20) NOT NULL,
    total DECIMAL(12, 2) NOT NULL,
    -- Plain words that say why the order was REJECTED
    reject_reason VARCHAR(500),
    -- Times are stored as UTC (hibernate.jdbc.time_zone=UTC in application-postgres.yml). The default says UTC too,
    -- so a row inserted without a time gets the same kind of value, whatever time zone the connection uses.
    created_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
    updated_at TIMESTAMP NOT NULL DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),

    -- Constraints
    CONSTRAINT chk_orders_status CHECK (status IN ('PENDING', 'CONFIRMED', 'REJECTED'))
);

-- One line per product. Name and unit price are a copy of what product-service said at checkout,
-- so a later price change does not change an old order.
CREATE TABLE IF NOT EXISTS order_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id BIGINT NOT NULL REFERENCES orders (id),
    sku_code VARCHAR(50) NOT NULL,
    name VARCHAR(255) NOT NULL,
    unit_price DECIMAL(10, 2) NOT NULL,
    quantity INT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_orders_user_id ON orders (user_id);
CREATE INDEX IF NOT EXISTS idx_order_items_order_id ON order_items (order_id);

-- updated_at is maintained by Hibernate's @UpdateTimestamp on the Order entity,
-- not a DB-level trigger (same as the other services).
